from pathlib import Path

LINES = Path('styles/uralla/lines')
TEST = Path('tests/test_marked_route_line_hierarchy.py')

text = LINES.read_text(encoding='utf-8')
old = '''# [CUSTOM/АВТОРСКОЕ] Marked route members switch to the close-zoom line one\n# level earlier and keep that same visual continuously through resolution 24.\n# These rules must stay before all base pedestrian/path/track rules: they own\n# marked ways completely, avoiding the old near -> far -> near sandwich.\nmkgmap:trail_name=* & highway=pedestrian & area!=yes & length()>100 [0x0e road_class=0 road_speed=0 resolution 21-24]\nmkgmap:trail_name=* & highway=cycleway & length()>100 [0x0e road_class=0 road_speed=1 resolution 21-24]\nmkgmap:trail_name=* & bicycle=yes & highway=path & length()>100 [0x16 road_class=0 road_speed=1 resolution 21-24]\nmkgmap:trail_name=* & highway=footway & length()>100 [0x0e road_class=0 road_speed=1 resolution 21-24]\nmkgmap:trail_name=* & bicycle!=yes & highway=path & length()>100 [0x16 road_class=0 road_speed=0 resolution 22-24]\nmkgmap:trail_name=* & highway=track & tracktype!=grade1 & length()>100 [0x13 road_class=0 road_speed=1 resolution 21-24]\nmkgmap:trail_name=* & highway=track & tracktype=grade1 & length()>100 [0x0a road_class=0 road_speed=1 resolution 20-24]\nmkgmap:trail_name=* & highway=bridleway & length()>100 [0x16 road_class=0 road_speed=0 resolution 23-24]\n'''
new = '''# [CUSTOM/АВТОРСКОЕ] Marked route members keep the same far/near visual hierarchy\n# as ordinary ways, but both thresholds are shifted one resolution farther out.\n# Never extend a marked route below resolution 20. These rules must stay before\n# the base pedestrian/path/track rules so marked ways are emitted only here.\nmkgmap:trail_name=* & highway=pedestrian & area!=yes & length()>100 [0x07 resolution 21-22 continue]\nmkgmap:trail_name=* & highway=pedestrian & area!=yes & length()>100 [0x0e road_class=0 road_speed=0 resolution 23-24]\nmkgmap:trail_name=* & highway=cycleway & length()>100 [0x07 resolution 21-22 continue]\nmkgmap:trail_name=* & highway=cycleway & length()>100 [0x0e road_class=0 road_speed=1 resolution 23-24]\nmkgmap:trail_name=* & bicycle=yes & highway=path & length()>100 [0x0b resolution 21-22 continue]\nmkgmap:trail_name=* & bicycle=yes & highway=path & length()>100 [0x16 road_class=0 road_speed=1 resolution 23-24]\nmkgmap:trail_name=* & highway=footway & length()>100 [0x07 resolution 21-22 continue]\nmkgmap:trail_name=* & highway=footway & length()>100 [0x0e road_class=0 road_speed=1 resolution 23-24]\nmkgmap:trail_name=* & bicycle!=yes & highway=path & length()>100 [0x0b resolution 22-22 continue]\nmkgmap:trail_name=* & bicycle!=yes & highway=path & length()>100 [0x16 road_class=0 road_speed=0 resolution 23-24]\nmkgmap:trail_name=* & highway=track & tracktype!=grade1 & length()>100 [0x12 resolution 21-22 continue]\nmkgmap:trail_name=* & highway=track & tracktype!=grade1 & length()>100 [0x13 road_class=0 road_speed=1 resolution 23-24]\nmkgmap:trail_name=* & highway=track & tracktype=grade1 & length()>100 [0x07 resolution 20-22 continue]\nmkgmap:trail_name=* & highway=track & tracktype=grade1 & length()>100 [0x0a road_class=0 road_speed=1 resolution 23-24]\nmkgmap:trail_name=* & highway=bridleway & length()>100 [0x16 road_class=0 road_speed=0 resolution 23-24]\n'''
if old not in text:
    raise SystemExit('current marked block not found exactly')
LINES.write_text(text.replace(old, new, 1), encoding='utf-8', newline='\n')

test = TEST.read_text(encoding='utf-8')
start = test.index('class MarkedRouteLineHierarchyTests')
head = test[:start]
body = '''class MarkedRouteLineHierarchyTests(unittest.TestCase):\n    def test_marked_routes_shift_far_and_near_one_level(self) -> None:\n        text = LINES.read_text(encoding="utf-8")\n        expected_pairs = (\n            ("mkgmap:trail_name=* & highway=pedestrian & area!=yes & length()>100 [0x07 resolution 21-22 continue]", "mkgmap:trail_name=* & highway=pedestrian & area!=yes & length()>100 [0x0e road_class=0 road_speed=0 resolution 23-24]"),\n            ("mkgmap:trail_name=* & highway=cycleway & length()>100 [0x07 resolution 21-22 continue]", "mkgmap:trail_name=* & highway=cycleway & length()>100 [0x0e road_class=0 road_speed=1 resolution 23-24]"),\n            ("mkgmap:trail_name=* & bicycle=yes & highway=path & length()>100 [0x0b resolution 21-22 continue]", "mkgmap:trail_name=* & bicycle=yes & highway=path & length()>100 [0x16 road_class=0 road_speed=1 resolution 23-24]"),\n            ("mkgmap:trail_name=* & highway=footway & length()>100 [0x07 resolution 21-22 continue]", "mkgmap:trail_name=* & highway=footway & length()>100 [0x0e road_class=0 road_speed=1 resolution 23-24]"),\n            ("mkgmap:trail_name=* & bicycle!=yes & highway=path & length()>100 [0x0b resolution 22-22 continue]", "mkgmap:trail_name=* & bicycle!=yes & highway=path & length()>100 [0x16 road_class=0 road_speed=0 resolution 23-24]"),\n            ("mkgmap:trail_name=* & highway=track & tracktype!=grade1 & length()>100 [0x12 resolution 21-22 continue]", "mkgmap:trail_name=* & highway=track & tracktype!=grade1 & length()>100 [0x13 road_class=0 road_speed=1 resolution 23-24]"),\n            ("mkgmap:trail_name=* & highway=track & tracktype=grade1 & length()>100 [0x07 resolution 20-22 continue]", "mkgmap:trail_name=* & highway=track & tracktype=grade1 & length()>100 [0x0a road_class=0 road_speed=1 resolution 23-24]"),\n        )\n        for far_rule, near_rule in expected_pairs:\n            self.assertIn(far_rule, text)\n            self.assertIn(near_rule, text)\n            self.assertLess(text.index(far_rule), text.index(near_rule))\n        self.assertIn("mkgmap:trail_name=* & highway=bridleway & length()>100 [0x16 road_class=0 road_speed=0 resolution 23-24]", text)\n        self.assertNotRegex(text, r"mkgmap:trail_name=.*resolution 1[0-9]")\n\n        first_marked = text.index(expected_pairs[0][0])\n        self.assertLess(first_marked, text.index("highway=pedestrian & area!=yes [0x07"))\n        self.assertLess(first_marked, text.index("highway=cycleway & length()>200 [0x07"))\n        self.assertLess(first_marked, text.index("bicycle=yes & highway=path & length()>100 [0x0b"))\n        self.assertLess(first_marked, text.index("highway=track & tracktype!=grade1 & length()>100"))\n\n    def test_unmarked_far_near_matrix_remains_intact(self) -> None:\n        text = LINES.read_text(encoding="utf-8")\n        for rule in (\n            "highway=cycleway & length()>200 [0x07 resolution 22-23 continue]",\n            "highway=cycleway [0x0e road_class=0 road_speed=1 resolution 24]",\n            "bicycle=yes & highway=path & length()>100 [0x0b resolution 22-23 continue]",\n            "bicycle=yes & highway=path [0x16 road_class=0 road_speed=1 resolution 24]",\n            "bicycle!=yes & highway=path & length()>100 [0x0b resolution 23-23 continue]",\n            "bicycle!=yes & highway=path [0x16 road_class=0 road_speed=0 resolution 24]",\n            "highway=track & tracktype=grade1 [0x0a road_class=0 road_speed=1 resolution 24]",\n            "highway=track & tracktype!=grade1 [0x13 road_class=0 road_speed=1 resolution 24]",\n        ):\n            self.assertIn(rule, text)\n\n\nif __name__ == "__main__":\n    unittest.main()\n'''
TEST.write_text(head + body, encoding='utf-8', newline='\n')
print('shifted marked far/near hierarchy by one resolution')
